spec.setup_code:
var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    // Angular acceleration demo: spin rate keeps increasing over time,
                    // just like a car whose speed keeps climbing under constant acceleration.
                    var angularAccel = 0.00005;
                    var spinRate = angularAccel * t;
                    cube.rotation.y += spinRate;
                  }
                };

var v0 = 0;
                var a = 40;
                var time = 0;
                return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    time += dt;
                    var margin = 40;
                    var travel = W - margin * 2;
                    var x0 = margin;
                    var dist = v0 * time + 0.5 * a * time * time;
                    if (dist > travel) { time = 0; dist = 0; }
                    var x = x0 + dist;
                    var y = H / 2;
                    var v = v0 + a * time;
                    ctx.fillStyle = '#8A9B6E';
                    ctx.fillRect(x0, y - 2, travel, 4);
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(x, y, 16, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#333333';
                    ctx.font = '14px sans-serif';
                    ctx.fillText('v = ' + v.toFixed(1) + ' m/s', 20, 30);
                  }
                };
